-- =============================================================================
-- Catálogo — MUDELAR igual aos Excels, ONDA 6: ATRIBUTOS dos produtos que não têm nenhum. MIGRATION DE DADOS.
-- Base de RH (uetjghdkwbywbftedtth).
-- =============================================================================
--
-- !!! SÓ PARA A BASE DE RH (uetjghdkwbywbftedtth). SÓ A MUDELAR (3242e925-da26-459a-8258-be04d904e355): todas as escritas
-- !!! levam o filtro da organização. Os ids, SKU e opções foram lidos na RH a 27/11/2026 (SELECT como administrador,
-- !!! sem RLS), depois da onda 4 (20270129800000). Noutra base (a principal) a organização ou os produtos não existem com
-- !!! estes ids, ou não há _mudelar_excel.onda3_produtos (a onda 3 não correu lá), e a migration sai por RAISE NOTICE
-- !!! sem escrever nada. RP0041 leva acabamento «Mate» (o Excel: «Natural»=Mate), não o «Natural» do nome. Antes do `db push`, confirmar
-- !!! supabase/.temp/project-ref = uetjghdkwbywbftedtth.
--
-- Pedido do dono: «eu só quero que os produtos que estão no modular sejam iguais aos do Excel» e «se são importados, a cor
-- ou alguma coisa deve vir, logo eles também não ficam sem atributo, né?». A 27/11 a Mudelar tinha 2443 produtos vivos sem
-- nenhum atributo (sem os 145 consumíveis CONS-): 2317 criados pela onda 3, 64 fichas dos negócios de 23/11, 6 de 20/11 e
-- 56 de 17/11 (com modelo). Plano gerado por script (mudelar-audit/onda6: o6_plan.py, o6_regras.py, o6_sql.py), fora da
-- pasta do projeto; o que fica de fora, com a razão e o valor candidato, está em mudelar-audit/onda6/fora.csv.
--
-- O QUE FAZ: dá 5263 valores de atributos a 2291 produtos que não tinham nenhum (1702 medidas e 3561 opções; por atributo:
-- medida 1702, lado 786, cor_corpo 669, tonalidade 612, largura 562, cor_frente 549, acabamento_frente 237, acabamento_corpo 117, acabamento 11, acabamento_cor 9, cor 9). Lista fechada, embutida abaixo; nada se calcula na hora.
-- Só se preenche o que é CERTO, e a prova é o próprio catálogo: cada regra foi corrida sobre os produtos JÁ COMPLETOS da
-- mesma subcategoria e só se usa onde acerta sempre (>= 5 acertos, 0 erros, 0 valores que a ficha não tem; ou, para um
-- valor só, >= 2 acertos e 0 falhas desse valor):
--   (a) MEDIDA do nome (NxM ou NxMxP, cm, pela ordem do nome, como as fichas completas; nunca com Ø nem com duas medidas
--       no nome) ou LARGURA («120cm») quando a subcategoria usa a largura e a opção existe;
--   (b) COR e ACABAMENTOS do nome: nos móveis e colunas pelo segmento «Corpo X, Frente Y Brilho» / «Corpo e Frente X» /
--       «Todo X» (corpo → cor_corpo ou acabamento_corpo, frente → cor_frente ou acabamento_frente, Brilho/Mate →
--       tonalidade); noutras subcategorias a palavra igual (sem acentos nem maiúsculas) a UMA opção ativa do atributo
--       que a subcategoria usa; LADO, VETA e PUXADOR pela palavra igual à opção;
--   (c) o Excel com UM só valor e a chave a dizer o atributo («Acabamento: Cromado»), igual a uma opção ativa.
-- Os «PAIS» (o Excel traz uma lista de cores, de frentes ou de tonalidades: a cor é um PRODUTO) recebem SÓ a medida ou a
-- largura, nunca cor, acabamento, tonalidade nem lado. Os legados com gémeo da onda 2 já tinham os atributos (0 aqui).
--
-- O QUE NÃO FAZ: não muda SKU (nenhuma chamada a cat_gerar_sku_produto; C3 exige 0 SKU alterados em TODOS os produtos da
-- Mudelar), não toca em nenhuma linha de products (C3 compara a linha inteira, updated_at incluído: nome, preços,
-- estado, subcategoria e modelo ficam), não dá modelo nem família, não cria opções nem atributos (os valores sem opção
-- ficam em fora.csv com a contagem), não altera nem apaga atributos que já existam (só entra em produtos SEM nenhum),
-- não toca em preços, famílias, documentos nem noutra organização.
--
-- GUARDAS (falham a migration inteira; nada fica): G0 a Mudelar existe (senão NOTICE e sai); L1 as listas têm os números
-- do cabeçalho; G1 548 famílias e 14637 membros (o total de produtos vivos só se regista: a onda 4b, aplicada à parte,
-- pode mudá-lo); G2 cada produto existe, é da Mudelar, está vivo, é produto do catálogo, tem o SKU lido, não tem modelo e
-- não está em família; G3 cada atributo é da Mudelar, vivo, com o código esperado, e cada opção existe ATIVA no grupo do
-- atributo (fn_cat_grupo_do_atributo, o mesmo que o ecrã usa); G4 nenhum produto da lista tem atributos (ou já todos
-- têm os desta onda: já aplicada, sai por NOTICE); G5 o utilizador da auditoria é membro ativo e a auditoria está
-- ligada; G6 os eixos das famílias têm valores distintos. Lock: pg_advisory_xact_lock(hashtextextended('cat_familias:'
-- || org, 0)) e os produtos FOR NO KEY UPDATE. ESCRITA: um só INSERT em product_attribute_values como
-- cat_guardar_produto_atributos grava (opção: value_text; medida: value_json com fn_cat_dimensao_medida, value_text com
-- fn_cat_dimensao_texto e unit), ON CONFLICT (product_id, attribute_id) DO NOTHING. Os gatilhos dessa tabela são só a
-- auditoria (AFTER) e o updated_at (BEFORE UPDATE). CONFERÊNCIAS no fim: C1 cada valor gravado e cada produto com
-- exatamente os da lista; C2 uma linha de auditoria por valor; C3 0 SKU alterados e products igual; C4 preços iguais;
-- C5 atributos que já existiam iguais e +5263 no total; C6 famílias (548 / 14637, impressão digital e eixos
-- distintos); C7 nada escrito fora dos atributos da Mudelar (xmin); C8 a cópia fechada (::text nas ACL e no relkind).
--
-- CÓPIA E REVERSÃO: as linhas de products tocadas ficam em _mudelar_excel.onda6_produtos e os atributos criados em
-- _mudelar_excel.onda6_atributos_novos (só postgres). REVERSÃO fora da pasta das migrations (estar aqui é ser aplicada):
-- mudelar-reverter-onda6.sql, guardado com o trabalho; apaga só as linhas desta onda que ainda estão como ela as escreveu.
--
-- ORDEM: depois de 20270129800000 (última no remoto RH a 27/11) e de 20270129850000 (onda 4b, se já estiver aplicada:
-- esta não depende dela). `supabase db push` aplica TUDO o que estiver pendente: listar com
-- `supabase migration list --linked` imediatamente antes e empurrar só esta.
-- =============================================================================

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '5min';

